 int dp(float v){return(int)(v*getContext().getResources().getDisplayMetrics().density+.5f);}String key(String k){return PlayerThemes.key(theme,k);}private TextView text(int size,int color){TextView t=new TextView(getContext());t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);t.setEllipsize(TextUtils.TruncateAt.END);return t;}private PlayerIconButton icon(int res,String label,boolean prominent){return new PlayerIconButton(getContext(),res,label,prominent);}private Button button(String name){Button b=new Button(getContext());b.setText(name);b.setTextSize(11);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(6),0,dp(6),0);LyricsPlayerBody.surface(b,0xcc29434f,dp(20));return b;}private static void value(TextView t,String s){if(!s.contentEquals(t.getText()))t.setText(s);}static String time(long ms){ms=Math.max(0,ms);return String.format(java.util.Locale.CHINA,"%02d:%02d",ms/60000,ms/1000%60);}
