 void appearance(){if(closed)return;LyricsAppearance a=LyricsAppearance.read(prefs);a.font=prefs.getInt(key("lyrics_font"),a.font);a.romanization=prefs.getBoolean(key("lyrics_romanization"),a.romanization);a.style=prefs.getInt(key("lyrics_style"),prefs.getInt("lyrics_style",theme.equals("immersive")?6:4));a.size=prefs.getInt(key("lyrics_size"),a.size);a.spacing=prefs.getInt(key("lyrics_spacing"),75);a.color=prefs.getInt(key("lyrics_color"),1);a.centered=prefs.getBoolean(key("lyrics_centered"),true);a.translation=prefs.getBoolean(key("lyrics_translation"),a.translation);a.reduceMotion=prefs.getBoolean(key("reduce_motion"),a.reduceMotion);try{a.systemReduceMotion=android.provider.Settings.Global.getFloat(getContext().getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}catch(Exception ignored){}quiet=a.quiet();stage.setAppearance(a);stage.setRenderActive(focused&&!preview);backdrop.scene(theme);backdrop.artwork(artwork,true);boolean light=theme.equals("minimal")&&prefs.getBoolean(key("light"),false)&&prefs.getInt(key("background_mode"),0)!=1;int accent=prefs.getInt(key("accent"),backdrop.accent());for(TextView t:new TextView[]{heading,title,artist,album,elapsed,duration})t.setTextColor(light?0xff324751:Color.WHITE);for(PlayerIconButton b:new PlayerIconButton[]{play,previous,next,shuffle,repeat,favorite,queue,lyrics,quality}){b.motion=!quiet;b.themePalette(light,accent);}if(root.getChildCount()>1){ViewGroup header=(ViewGroup)root.getChildAt(1);for(int i=0;i<header.getChildCount();i++)if(header.getChildAt(i) instanceof PlayerIconButton)((PlayerIconButton)header.getChildAt(i)).themePalette(light,accent);}progress.style=prefs.getInt(key("progress"),0);progress.color=accent;progress.setProgressTintList(ColorStateList.valueOf(accent));progress.setThumbTintList(ColorStateList.valueOf(light?0xff365865:Color.WHITE));progress.setProgressBackgroundTintList(ColorStateList.valueOf(0x558ba9b6));progress.setSecondaryProgressTintList(ColorStateList.valueOf(0x889ec3ce));if(glassPanel!=null){glassPanel.release();glassPanel=null;}if(theme.equals("glass")){GradientDrawable glass=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0x88426978,0x55405b6c});glass.setCornerRadius(dp(24));glass.setStroke(dp(1),0x66c4e5ef);controls.setBackground(glass);}else controls.setBackgroundColor(Color.TRANSPARENT);artworkView.theme(theme,accent,light,prefs.getInt(key("spectrum_style"),0),prefs.getInt(key("sensitivity"),100)/100f);body.requestLayout();}
 private String artists(JSONObject track){if(track==null)return "未知歌手";JSONArray a=track.optJSONArray("artists");StringBuilder s=new StringBuilder();if(a!=null)for(int i=0;i<Math.min(3,a.length());i++){String name=a.optJSONObject(i)==null?a.optString(i):a.optJSONObject(i).optString("name");if(s.length()>0)s.append(" / ");s.append(name);}return s.length()>0?s.toString():track.optString("artist","未知歌手");}
 void refresh(){if(closed)return;PlaybackService.Snapshot s=host.state();boolean changed=!s.uri.equals(uri);if(s.generation!=generation){stage.cancelInteraction();stage.follow();generation=s.generation;if(seeking)cancelled=true;}if(changed){if(timingDialog!=null)timingDialog.dismiss();uri=s.uri;timing.select(uri);stage.setTimeline(LyricsTimeline.empty());stage.setMessage("正在获取歌词");if(!preview&&!uri.isEmpty())host.loadThemeLyrics(uri,this);else if(uri.isEmpty())stage.setMessage("选择一首歌曲开始播放");}String name=s.track==null?s.title:s.track.optString("name",s.title),author=artists(s.track);value(heading,PlayerThemes.NAMES[PlayerThemes.index(theme)]+"  ·  "+(name.isEmpty()?"尚未选择歌曲":name));value(title,name.isEmpty()?"选择一首歌曲":name);value(artist,author);JSONObject al=s.track==null?null:s.track.optJSONObject("album");value(album,al==null?"专辑信息未提供":al.optString("name","专辑信息未提供"));Bitmap current=host.artwork(uri);if(current!=artwork){artwork=current;artworkView.art(current);stage.setArtwork(current);backdrop.artwork(current,false);appearance();if(!quiet&&current!=null&&!preview){artworkView.setAlpha(.4f);artworkView.setScaleX(.97f);artworkView.setScaleY(.97f);artworkView.animate().alpha(1).scaleX(1).scaleY(1).setDuration(260).start();}}backdrop.state(s.position,s.playing,quiet);artworkView.state(name,author,s.position,s.duration,s.playing&&!s.buffering,focused&&!preview,quiet);play.icon(s.playing?R.drawable.player_pause:R.drawable.player_play);play.describe(s.playing?"暂停播放":"开始播放");shuffle.setChecked(s.shuffle);repeat.setChecked(s.repeat);repeat.icon(s.repeat?R.drawable.player_repeat_1:R.drawable.player_repeat);favorite.setChecked(host.liked(uri));favorite.setEnabled(host.canLike(uri)&&!host.likePending(uri)&&!uri.isEmpty());progress.setEnabled(s.ready&&s.duration>0);progress.active=focused&&s.playing;if(!seeking){progress.setProgress(s.duration>0?(int)(s.position*10000L/s.duration):0);value(elapsed,time(s.position));value(duration,s.duration>0?time(s.duration):"时长未知");}progress.setSecondaryProgress(s.buffered*100);value(info,"歌曲  "+name+"\n歌手  "+author+"\n专辑  "+album.getText()+"\n来源  "+host.source(s)+"\n音质  "+s.qualityInfo+"\n歌词精度  "+(stage.timeline().estimatedWordTiming?"行时间，逐字为估算":stage.timeline().wordTimed?"音源逐字时间":"未提供时间")+"\n速度  "+s.speed+"×\n音量  "+s.volume+"%");if(queueView.getVisibility()==View.VISIBLE)queueView.refresh(false);if(floatingQueue!=null&&queueDialog!=null&&queueDialog.isShowing())floatingQueue.refresh(false);audio.setText(AudioAnalysis.authorized?"真实音频分析设置":"开启真实音频分析");if(!preview)AudioAnalysis.demand(focused&&(PlayerThemes.audio(theme)||progress.style==2),s.playing,s.remote);stage.invalidate();}
 void sessionChanged(){if(closed||!isShowing())return;PlaybackService.Snapshot s=host.state();if(timingDialog!=null&&!s.uri.equals(uri))timingDialog.dismiss();if(focused)refresh();else if(s.generation!=generation||!s.uri.equals(uri)){stage.cancelInteraction();stage.follow();}}
 private void browseChanged(){if(browse==null)return;long ms=stage.browseStart();browse.setVisibility(ms>=0&&stage.getVisibility()==View.VISIBLE?View.VISIBLE:View.GONE);if(ms>=0)playLine.setText(time(ms)+"  播放这句");}
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION);}
 private void seek(){progress.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN)cancelled=false;else if(e.getActionMasked()==MotionEvent.ACTION_CANCEL)cancelled=true;return false;});progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){PlaybackService.Snapshot s=host.state();seeking=true;seekGeneration=s.generation;seekUri=s.uri;seekDuration=s.duration;seekPreview=(int)(seekDuration*(long)b.getProgress()/10000L);}public void onProgressChanged(SeekBar b,int p,boolean user){if(!user)return;if(seeking){seekPreview=(int)(seekDuration*(long)p/10000L);value(elapsed,time(seekPreview));}else{PlaybackService.Snapshot s=host.state();if(s.ready&&s.duration>0)host.seek((int)(s.duration*p/10000L));}}public void onStopTrackingTouch(SeekBar b){PlaybackService.Snapshot s=host.state();boolean commit=seeking&&!cancelled&&s.generation==seekGeneration&&s.uri.equals(seekUri)&&seekDuration>0;seeking=false;if(commit)host.seek(seekPreview);refresh();}});}
 private void gesture(View view,boolean header){view.setOnClickListener(v->{if(header)showThemes();else setTheme("immersive",true);});view.setOnTouchListener(new View.OnTouchListener(){float x,y;long gen;String track;public boolean onTouch(View v,MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();gen=host.state().generation;track=host.state().uri;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){float dx=e.getX()-x,dy=e.getY()-y;if(host.state().generation!=gen||!track.equals(host.state().uri))return true;if(Math.abs(dy)>dp(60)&&Math.abs(dy)>Math.abs(dx)){int i=PlayerThemes.index(theme);setTheme(PlayerThemes.IDS[(i+(dy<0?1:PlayerThemes.IDS.length-1))%PlayerThemes.IDS.length],true);}else if(Math.abs(dx)>dp(64)){if(dx<0)host.next();else host.previous();refresh();}else if(Math.max(Math.abs(dx),Math.abs(dy))<dp(12))v.performClick();}return true;}});}
 void showThemes(){if(themeCenter!=null&&themeCenter.isShowing())return;themeCenter=new ThemeCenter(activity,this);themeCenter.show();}
 private void more(View anchor){PopupMenu menu=new PopupMenu(getContext(),anchor);String[] items={"播放主题中心","歌词外观与动效","当前主题背景","播放队列","播放速度","播放音量","音效与均衡器","播放音质","定时暂停","完整歌词与导入","歌曲评论","主题独立设置","添加歌曲到队列","停止音频分析","屏幕方向","收藏或取消收藏","播放设备"};for(int i=0;i<items.length;i++)menu.getMenu().add(0,i,i,items[i]);menu.setOnMenuItemClickListener(item->{switch(item.getItemId()){case 0:showThemes();break;case 1:lyricSettings();break;case 2:backgroundSettings();break;case 3:showQueue();break;case 4:speed();break;case 5:volume();break;case 6:host.effects();break;case 7:host.quality();break;case 8:host.sleep();break;case 9:host.lyrics();break;case 10:host.comments();break;case 11:themeSettings();break;case 12:host.queueAdd();break;case 13:getContext().startService(new Intent(getContext(),PlayerAudioCaptureService.class).setAction("stop"));break;case 14:new AlertDialog.Builder(activity).setTitle("屏幕方向").setItems(new String[]{"横屏播放","竖屏播放","随设备旋转"},(d,n)->{int orientation=new int[]{android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,android.content.pm.ActivityInfo.SCREEN_ORIENTATION_FULL_SENSOR}[n];prefs.edit().putInt("player_orientation",orientation).apply();activity.setRequestedOrientation(orientation);}).show();break;case 15:if(host.canLike(uri))host.like();refresh();break;case 16:if(host.devices())host.showDevices();else Toast.makeText(activity,"当前音源没有远程设备控制",Toast.LENGTH_SHORT).show();break;}return true;});menu.show();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);focused=focus;artworkView.active(focus&&!preview);stage.setRenderActive(focus&&!preview);handler.removeCallbacks(tick);if(focus&&isShowing()){immersive();handler.post(tick);}else if(!preview)AudioAnalysis.demand(false,false,false);}
 @Override protected void onStop(){handler.removeCallbacks(tick);artworkView.active(false);stage.setRenderActive(false);if(!preview)AudioAnalysis.demand(false,false,false);super.onStop();}
 @Override public void dismiss(){if(closed)return;closed=true;prefs.unregisterOnSharedPreferenceChangeListener(listener);handler.removeCallbacksAndMessages(null);if(themeCenter!=null)themeCenter.dismiss();if(settingsDialog!=null)settingsDialog.dismiss();if(backgroundDialog!=null)backgroundDialog.dismiss();if(timingDialog!=null)timingDialog.dismiss();if(queueDialog!=null)queueDialog.dismiss();if(!preview)AudioAnalysis.demand(false,false,false);if(glassPanel!=null)glassPanel.release();artworkView.release();stage.release();backdrop.release();super.dismiss();}
 void backgroundChanged(){appearance();}
 private LinearLayout form(){LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(dp(16),dp(8),dp(16),dp(8));return box;}
 private void slider(LinearLayout box,String label,String property,int initial,int min,int max){TextView caption=text(13,Color.WHITE);caption.setText(label+"  "+initial);box.addView(caption,new LinearLayout.LayoutParams(-1,dp(30)));SeekBar bar=new SeekBar(activity);bar.setContentDescription(label);bar.setMax(max-min);bar.setProgress(initial-min);box.addView(bar,new LinearLayout.LayoutParams(-1,dp(48)));final String selectedTheme=theme;bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){if(user){caption.setText(label+"  "+(v+min));prefs.edit().putInt(PlayerThemes.key(selectedTheme,property),v+min).apply();}}});}
 private void choice(LinearLayout box,String label,String property,String[] labels,int initial){Button b=button(label+"："+labels[Math.max(0,Math.min(labels.length-1,initial))]);box.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));final String selectedTheme=theme;b.setOnClickListener(v->new AlertDialog.Builder(activity).setTitle(label).setSingleChoiceItems(labels,prefs.getInt(PlayerThemes.key(selectedTheme,property),initial),(d,n)->{prefs.edit().putInt(PlayerThemes.key(selectedTheme,property),n).apply();b.setText(label+"："+labels[n]);d.dismiss();}).setNegativeButton("取消",null).show());}
