 private AlertDialog formDialog(String name,LinearLayout content){ScrollView scroll=new ScrollView(activity);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(name).setView(scroll).setPositiveButton("完成",null).create();dialog.show();return dialog;}
 private void backgroundSettings(){LinearLayout box=form();choice(box,"背景来源","background_mode",new String[]{"跟随歌曲封面","自定义图片","动态渐变"},0);Button photo=button("选择自定义背景图片");box.addView(photo,new LinearLayout.LayoutParams(-1,dp(48)));photo.setOnClickListener(v->host.pickBackground());slider(box,"背景模糊","blur",prefs.getInt(key("blur"),24),0,80);slider(box,"背景亮度","brightness",prefs.getInt(key("brightness"),100),20,150);slider(box,"图片透明度","opacity",prefs.getInt(key("opacity"),100),0,100);slider(box,"暗色遮罩","shade",prefs.getInt(key("shade"),44),0,90);backgroundDialog=formDialog("当前主题背景",box);}
 private void lyricSettings(){LinearLayout box=form();choice(box,"歌词字体","lyrics_font",new String[]{"系统字体","衬线字体","等宽字体"},0);check(box,"显示音译，需音源提供","lyrics_romanization",true);choice(box,"歌词动画","lyrics_style",LyricsAppearance.STYLES,prefs.getInt(key("lyrics_style"),6));choice(box,"歌词颜色","lyrics_color",LyricsAppearance.COLORS,1);slider(box,"歌词大小","lyrics_size",prefs.getInt(key("lyrics_size"),100),80,135);slider(box,"行间距离","lyrics_spacing",prefs.getInt(key("lyrics_spacing"),85),75,150);check(box,"显示翻译","lyrics_translation",true);check(box,"歌词居中","lyrics_centered",true);check(box,"减少动态效果","reduce_motion",false);Button timingButton=button("同步与时间偏移");box.addView(timingButton,new LinearLayout.LayoutParams(-1,dp(48)));timingButton.setOnClickListener(v->{if(settingsDialog!=null)settingsDialog.dismiss();showTiming();});settingsDialog=formDialog("当前主题歌词",box);}
 private void themeSettings(){LinearLayout box=form();choice(box,"进度条","progress",new String[]{"精细线条","柔光进度","实时音频波形"},0);if(PlayerThemes.audio(theme)){choice(box,"频谱样式","spectrum_style",new String[]{"柱形频谱","环形频谱","双声道波形"},0);slider(box,"频谱灵敏度","sensitivity",prefs.getInt(key("sensitivity"),100),25,250);TextView status=text(12,Color.WHITE);status.setText(AudioAnalysis.status);box.addView(status);Button capture=button("授权真实音频分析");box.addView(capture,new LinearLayout.LayoutParams(-1,dp(48)));capture.setOnClickListener(v->host.requestAnalysis());}choice(box,"主题强调色","palette",new String[]{"跟随封面","薄荷绿","暖金色","樱花粉","冰蓝紫"},0);Button tint=button("应用强调色");box.addView(tint,new LinearLayout.LayoutParams(-1,dp(48)));tint.setOnClickListener(v->{int p=prefs.getInt(key("palette"),0);if(p==0)prefs.edit().remove(key("accent")).apply();else prefs.edit().putInt(key("accent"),new int[]{0,0xffa6e7d5,0xffffd391,0xffffb1cf,0xffb6b6ff}[p]).apply();});if(theme.equals("minimal"))check(box,"浅色主题","light",false);check(box,"减少动态效果","reduce_motion",false);Button reset=button("恢复当前主题默认设置");box.addView(reset,new LinearLayout.LayoutParams(-1,dp(48)));reset.setOnClickListener(v->{PlayerThemes.reset(prefs,theme);if(settingsDialog!=null)settingsDialog.dismiss();});settingsDialog=formDialog("主题独立设置",box);}
 void showTiming(){String selected=uri;LinearLayout box=form();TextView label=text(14,Color.WHITE);label.setText("歌词偏移 "+timing.offset()+" 毫秒");box.addView(label);for(int amount:new int[]{-200,200,0}){Button b=button(amount==0?"恢复同步":amount<0?"提前 0.2 秒":"延后 0.2 秒");box.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));b.setOnClickListener(v->{if(!selected.equals(host.state().uri)){timingDialog.dismiss();return;}if(amount==0)timing.set(0);else timing.adjust(amount);label.setText("歌词偏移 "+timing.offset()+" 毫秒");stage.follow();});}timingDialog=formDialog("调整这首歌的歌词同步",box);}
 private void speed(){String[] speeds={"0.5×","0.75×","1×","1.25×","1.5×","1.75×","2×"};float[] values={.5f,.75f,1,1.25f,1.5f,1.75f,2};new AlertDialog.Builder(activity).setTitle("播放速度").setItems(speeds,(d,n)->{if(!host.setSpeed(values[n]))Toast.makeText(activity,"当前播放设备或音频不支持倍速",Toast.LENGTH_LONG).show();}).setNegativeButton("取消",null).show();}
 private void volume(){host.volume();}
 private void showQueue(){ThemeQueueView list=new ThemeQueueView(activity,host,null);floatingQueue=list;queueDialog=new AlertDialog.Builder(activity).setTitle("播放队列，长按手柄拖动排序").setView(list).setNegativeButton("关闭",null).create();list.refresh(true);queueDialog.show();queueDialog.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-dp(24),dp(620)),Math.min(activity.getResources().getDisplayMetrics().heightPixels-dp(32),dp(480)));}
 Bitmap preview(String id,Bitmap photo){ThemedPlayerDialog page=new ThemedPlayerDialog(activity,host,true);page.setTheme(id,false);page.backdrop.previewPhoto(photo);page.stage.setTimeline(stage.timeline());int w=dp(640),h=dp(360);page.root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));page.root.layout(0,0,w,h);Bitmap result=Bitmap.createBitmap(640,360,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);canvas.scale(640f/w,360f/h);page.root.draw(canvas);page.dismiss();return result;}
 final class SceneBody extends ViewGroup {
  private final java.util.HashSet<View> shown=new java.util.HashSet<>();
  SceneBody(Context c){super(c);setClipChildren(true);}
  private void place(View v,int x,int y,int w,int h){shown.add(v);v.setVisibility(VISIBLE);v.measure(MeasureSpec.makeMeasureSpec(Math.max(0,w),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(0,h),MeasureSpec.EXACTLY));v.layout(x,y,x+Math.max(0,w),y+Math.max(0,h));}
  @Override protected void onMeasure(int ws,int hs){setMeasuredDimension(MeasureSpec.getSize(ws),MeasureSpec.getSize(hs));}
  @Override protected void onLayout(boolean changed,int l,int t,int r,int b){int w=r-l,h=b-t;shown.clear();boolean wide=w>=dp(580)&&w>h*1.2;int top=dp(52),gap=dp(16),bottom=dp(104);if(theme.equals("immersive")){place(stage,0,top,w,Math.max(dp(48),h-top-bottom));place(controls,0,h-bottom,w,bottom);}else if(wide){int left=Math.min(Math.max(dp(280),(int)(w*.45f)),w-dp(280)-gap),x=left+gap,right=w-x;if(theme.equals("vinyl")){int side=Math.max(0,Math.min(left-dp(16),h-top-bottom));place(artworkView,(left-side)/2,top,side,side);place(controls,0,h-bottom,left,bottom);place(stage,x,top,right,h-top-dp(48));place(shortcuts,x,h-dp(48),right,dp(48));}else if(theme.equals("professional")){int side=Math.max(0,Math.min(left-dp(12),h-top));place(artworkView,(left-side)/2,top+(h-top-side)/2,side,side);place(metadata,x,top,right,dp(57));place(tabs,x,top+dp(57),right,dp(48));int y=top+dp(105),height=Math.max(0,h-bottom-y);View content=tab.equals("queue")?queueView:tab.equals("info")?information:stage;place(content,x,y,right,height);place(controls,x,h-bottom,right,bottom);}else{int reserve=PlayerThemes.audio(theme)?dp(48):0,side=Math.max(0,Math.min(left-dp(16),h-top-reserve));place(artworkView,(left-side)/2,top+(h-top-reserve-side)/2,side,side);int y=Math.max(top,(h-dp(220))/2);place(metadata,x,y,right,dp(57));place(controls,x,y+dp(64),right,bottom);place(shortcuts,x,y+dp(172),right,dp(48));if(PlayerThemes.audio(theme))place(audio,0,h-dp(48),left,dp(48));}}else{if(theme.equals("professional")){int side=Math.max(0,Math.min(w-dp(32),h-dp(370)));place(artworkView,(w-side)/2,top,side,side);int y=top+side+dp(8);place(metadata,dp(8),y,w-dp(16),dp(57));y+=dp(57);place(tabs,0,y,w,dp(48));y+=dp(48);place(tab.equals("queue")?queueView:tab.equals("info")?information:stage,0,y,w,Math.max(0,h-bottom-y));place(controls,0,h-bottom,w,bottom);}else{int reserve=PlayerThemes.audio(theme)?dp(48):0,side=Math.max(0,Math.min(w-dp(32),h-top-dp(235)-reserve));place(artworkView,(w-side)/2,top,side,side);place(metadata,dp(8),top+side+dp(8),w-dp(16),dp(57));place(controls,0,h-bottom-dp(48)-reserve,w,bottom);place(shortcuts,0,h-dp(48)-reserve,w,dp(48));if(reserve>0)place(audio,0,h-dp(48),w,dp(48));}}if(theme.equals("glass")&&glassPanel==null&&controls.getWidth()>0){glassPanel=new ThemeGlass(backdrop,controls.getWidth(),controls.getHeight(),dp(24));controls.setBackground(glassPanel);}if(shown.contains(stage)&&stage.browseStart()>=0)place(browse,stage.getLeft(),stage.getBottom()-dp(48),stage.getWidth(),dp(48));for(int i=0;i<getChildCount();i++)if(!shown.contains(getChildAt(i)))getChildAt(i).setVisibility(GONE);}
 }
